:dep serde_json = "=1.0.149"
use std::io::Write;
{
    let root=std::path::Path::new("/Users/kevintruong/project/SpurCode/.spur/artifacts/cpp-gap-repository-index");
    let out=root.join("change-context-graph");
    std::fs::create_dir_all(&out)?;
    let paths: Vec<std::path::PathBuf>=std::fs::read_to_string(root.join("head-cpp-paths.txt"))?.lines().map(std::path::PathBuf::from).collect();
    let facts=spur_graph::extract::tree_sitter::build_facts_for_paths(&root.join("head-cpp-sources"),&paths)?;
    let mut nodes=std::io::BufWriter::new(std::fs::File::create(out.join("nodes.json"))?);
    serde_json::to_writer(&mut nodes,&facts.nodes)?; nodes.flush()?;
    let mut edges=std::io::BufWriter::new(std::fs::File::create(out.join("edges.json"))?);
    serde_json::to_writer(&mut edges,&facts.edges)?; edges.flush()?;
    let mut spans=std::io::BufWriter::new(std::fs::File::create(out.join("spans.json"))?);
    serde_json::to_writer(&mut spans,&facts.spans)?; spans.flush()?;
    println!("Pinned repository graph exported: {} files, {} nodes, {} edges; source spans retained",paths.len(),facts.nodes.len(),facts.edges.len());
}
